await page.goto('/ops/radar');
const main = page.getByRole('main');
await expect(main).toBeVisible();
await expect(main).toHaveCSS('flex-direction', 'column');
const feed = (await page.getByRole('feed').count()) > 0
  ? page.getByRole('feed').first()
  : page.getByRole('list').first();
await expect(feed).toBeVisible();
await expect(feed).toHaveCSS('flex-direction', 'column');
